"COM_PRIVACY_ERROR_CHECKING_FOR_EXISTING_REQUESTS" => "เกิดข้อผิดพลาดในการตรวจสอบคำขอข้อมูลที่มีอยู่ โปรดลองส่งคำขอนี้อีกครั้ง",
"COM_PRIVACY_ERROR_CONFIRM_TOKEN_EXPIRED" => "โทเค็นการยืนยันสำหรับคำขอข้อมูลของคุณหมดอายุแล้ว คุณจะต้องส่งคำขอใหม่",
