'COM_USERS_EMAIL_ACCOUNT_DETAILS' => 'รายละเอียดบัญชีสำหรับ {NAME} ที่ {SITENAME}',
'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_BODY' => "สวัสดี {NAME},\n\nบัญชีของคุณถูกเปิดใช้งานโดยผู้ดูแลระบบ ตอนนี้คุณสามารถเข้าสู่ระบบได้ที่ {SITEURL} โดยใช้ชื่อผู้ใช้ {USERNAME} และรหัสผ่านที่คุณเลือกใช้ตอนลงทะเบียน",
'COM_USERS_EMAIL_ACTIVATED_BY_ADMIN_ACTIVATION_SUBJECT' => 'เปิดใช้งานบัญชีสำหรับ {NAME} ที่ {SITENAME}',
'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_BODY' => "สวัสดีผู้ดูแลระบบ,\n\nผู้ใช้ใหม่ได้ลงทะเบียนที่ {SITENAME}\nผู้ใช้ได้ยืนยันที่อยู่อีเมลและขอให้คุณอนุมัติบัญชีของเขา\nอีเมลนี้มีรายละเอียด:\n\n  ชื่อ :  {NAME} \n  อีเมล:  {EMAIL} \n  ชื่อผู้ใช้:  {USERNAME} \n\nคุณสามารถเปิดใช้งานผู้ใช้โดยเลือกจากลิงก์ด้านล่าง:\n{ACTIVATE}",
'COM_USERS_EMAIL_ACTIVATE_WITH_ADMIN_ACTIVATION_SUBJECT' => 'การอนุมัติการลงทะเบียนที่จำเป็นสำหรับบัญชีของ {NAME} ที่ {SITENAME}',
'COM_USERS_EMAIL_PASSWORD_RESET_BODY' => "สวัสดี,\n\nมีการร้องขอให้รีเซ็ตรหัสผ่านบัญชีของคุณ {SITENAME} ในการรีเซ็ตรหัสผ่าน คุณจะต้องส่งรหัสยืนยันนี้เพื่อยืนยันว่าคำขอนั้นถูกต้อง\n\nรหัสยืนยันคือ {TOKEN}\n\nเลือก URL ด้านล่างและดำเนินการรีเซ็ตรหัสผ่านของคุณ\n\n{LINK_TEXT} \n\nขอบคุณ",
'COM_USERS_EMAIL_PASSWORD_RESET_SUBJECT' => 'คุณ {SITENAME} ได้ขอรีเซ็ตรหัสผ่าน',
'COM_USERS_EMAIL_REGISTERED_BODY' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME}\n\nตอนนี้คุณสามารถเข้าสู่ระบบ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านต่อไปนี้:\n\nชื่อผู้ใช้: {USERNAME}\nรหัสผ่าน: {PASSWORD_CLEAR}",
'COM_USERS_EMAIL_REGISTERED_BODY_NOPW' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME}\n\nตอนนี้คุณสามารถเข้าสู่ระบบ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านที่คุณลงทะเบียนเอาไว้",
'COM_USERS_EMAIL_REGISTERED_NOTIFICATION_TO_ADMIN_BODY' => "สวัสดีผู้ดูแลระบบ, \n\nผู้ใช้ใหม่ '{NAME}', ชื่อผู้ใช้ '{USERNAME}', ได้ลงทะเบียนที่ {SITEURL}",
'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME} บัญชีของคุณถูกสร้างขึ้น และต้องเปิดใช้งานก่อนจึงจะสามารถใช้งานได้\nในการเปิดใช้งานบัญชี ให้เลือกลิงก์ต่อไปนี้หรือคัดลอก และวางในเบราว์เซอร์ของคุณ:\n{ACTIVATE} \n\nหลังจากเปิดใช้งานคุณสามารถเข้าสู่ระบบที่ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านต่อไปนี้:\n\nชื่อผู้ใช้: {USERNAME}\nรหัสผ่าน: {PASSWORD_CLEAR}",
'COM_USERS_EMAIL_REGISTERED_WITH_ACTIVATION_BODY_NOPW' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME} บัญชีของคุณถูกสร้างขึ้น และต้องเปิดใช้งานก่อนจึงจะสามารถใช้งานได้\nในการเปิดใช้งานบัญชี ให้เลือกลิงก์ต่อไปนี้หรือคัดลอก และวางในเบราว์เซอร์ของคุณ:\n{ACTIVATE} \n\nหลังจากเปิดใช้งานคุณสามารถเข้าสู่ระบบที่ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านต่อไปนี้ที่คุณป้อนระหว่างการลงทะเบียน:\n\nชื่อผู้ใช้: {USERNAME}",
'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME} บัญชีของคุณถูกสร้างขึ้น และต้องได้รับการยืนยันก่อนจึงจะสามารถใช้งานได้\n\nในการยืนยันบัญชี ให้เลือกลิงก์ต่อไปนี้หรือคัดลอก และวางในเบราว์เซอร์ของคุณ:\n{ACTIVATE} \n\nหลังจากการตรวจสอบแล้ว ผู้ดูแลระบบจะแจ้งให้ทราบเพื่อเปิดใช้งานบัญชีของคุณ คุณจะได้รับการยืนยันเมื่อดำเนินการเสร็จสิ้น\n\nเมื่อเปิดใช้งานบัญชีนั้นแล้ว คุณสามารถเข้าสู่ระบบที่ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านต่อไปนี้:\n\nชื่อผู้ใช้: {USERNAME}\nรหัสผ่าน: {PASSWORD_CLEAR}",
'COM_USERS_EMAIL_REGISTERED_WITH_ADMIN_ACTIVATION_BODY_NOPW' => "สวัสดี {NAME},\n\nขอบคุณสำหรับการลงทะเบียนที่ {SITENAME} บัญชีของคุณถูกสร้างขึ้น และต้องได้รับการยืนยันก่อนจึงจะสามารถใช้งานได้\n\nในการยืนยันบัญชี ให้เลือกลิงก์ต่อไปนี้หรือคัดลอก และวางในเบราว์เซอร์ของคุณ:\n{ACTIVATE} \n\nหลังจากการตรวจสอบแล้ว ผู้ดูแลระบบจะแจ้งให้ทราบเพื่อเปิดใช้งานบัญชีของคุณ คุณจะได้รับการยืนยันเมื่อดำเนินการเสร็จสิ้น\n\nเมื่อเปิดใช้งานบัญชีนั้นแล้ว คุณสามารถเข้าสู่ระบบ {SITEURL} โดยใช้ชื่อผู้ใช้และรหัสผ่านต่อไปนี้ที่คุณป้อนระหว่างการลงทะเบียน:\n\nชื่อผู้ใช้: {USERNAME}",
'COM_USERS_EMAIL_USERNAME_REMINDER_BODY' => "สวัสดี,\n\nมีการร้องขอการแจ้งเตือนชื่อผู้ใช้สำหรับบัญชี {SITENAME} ของคุณ\n\nชื่อผู้ใช้ของคุณ: {USERNAME}\n\nในการเข้าสู่ระบบบัญชีของคุณ เลือกจากลิงก์ด้านล่าง\n\n{LINK_TEXT} \n\nขอบคุณ",
